// Supplied creator-list redesign. Fonts embedded under SIL OFL-1.1.
export const QUOTATION_LIST_REDESIGN_CSS = "/* =====================================================================\n   CREATOR LIST \u00e2\u20ac\u201d DESIGN TOKENS\n   Single source of truth for colour, type, spacing, radius and shadow.\n   Every value in creator-list.css references these variables.\n   ===================================================================== */\n\n/* ---------- Fonts (self-hosted; files in /fonts, OFL-1.1) ----------\n   Self-host rather than Google Fonts so headless PDF export never\n   falls back to Arial. Adjust the url() paths to where you serve them. */\n@font-face{font-family:'Geist';src:url('data:font/woff2;base64,') format('woff2');\n  font-weight:100 900;font-style:normal;font-display:block}\n@font-face{font-family:'Geist Mono';src:url('data:font/woff2;base64,') format('woff2');\n  font-weight:500;font-style:normal;font-display:block}\n@font-face{font-family:'Geist Mono';src:url('data:font/woff2;base64,') format('woff2');\n  font-weight:700;font-style:normal;font-display:block}\n\n:root{\n  /* ---------- Type families ---------- */\n  --font-sans:'Geist','Helvetica Neue',Arial,Helvetica,sans-serif;\n  --font-mono:'Geist Mono',ui-monospace,'SF Mono',Menlo,monospace;\n\n  /* ---------- Page surfaces (dark, unchanged from original) ---------- */\n  --navy:        #050443;  /* page background */\n  --panel-top:   #262263;  /* card tray gradient start */\n  --panel:       #211e5c;  /* card tray gradient end */\n  --strip:       #25225f;  /* legend bar, cover strip */\n  --line-dark:   rgba(255,255,255,.14);   /* hairlines on navy */\n  --line-dark-2: rgba(255,255,255,.07);   /* tray border */\n\n  /* ---------- Brand accent ---------- */\n  --pink:        #ff3da8;  /* page range, Option 2 tag, cover count */\n  --pink-soft:   #ff7cc4;  /* eyebrows on navy */\n\n  /* ---------- Text on navy ---------- */\n  --on-dark:     #ffffff;\n  --on-dark-2:   #c4c1d6;  /* secondary */\n  --on-dark-3:   #aaa6cf;  /* labels, footer */\n\n  /* ---------- Card surface + text on white ---------- */\n  --card:        #ffffff;\n  --ink:         #080642;  /* primary text, Option 1 tag fill */\n  --ink-2:       #3f3c63;  /* stat values */\n  --ink-3:       #5d5b70;  /* handle, money breakdown, \"EGP\" */\n  --ink-4:       #77748f;  /* table column headers */\n  --ink-muted:   #8d8aa5;  /* empty-state italic */\n  --ink-off:     #b3b0c6;  /* \"\u00e2\u20ac\u201d\" for missing platform */\n  --hair:        #e7e5f0;  /* divider above audience */\n  --hair-dash:   #d8d5e6;  /* dashed divider above breakdown */\n  --portrait-bg: #efedf4;\n\n  /* ---------- Tier pills (text \u00e2\u2030\u00a5 4.5:1 on fill) ---------- */\n  --mega-bg:#ffe0f1;  --mega-fg:#a3005f;\n  --macro-bg:#e6e3ff; --macro-fg:#3a2db3;\n  --mid-bg:#d9f2ea;   --mid-fg:#0c6650;\n  --nano-bg:#fdecc8;  --nano-fg:#7d4a00;\n\n  /* ---------- Offer blocks ---------- */\n  --offer1-bg:   #f2f1f9;  /* Option 1 + Package block */\n  --offer2-bg:   #fff0f7;  /* Option 2 block */\n  --offer-empty: #d6d3e4;  /* dashed border of an empty slot */\n  --tag1-bg:     #080642;  --tag1-fg:#ffffff;   /* Option 1 / Package */\n  --tag2-bg:     #ff3da8;  --tag2-fg:#080642;   /* Option 2 (navy on pink = 5.1:1) */\n\n  /* ---------- Deliverable chips (white fill, coloured border + text) ---------- */\n  --chip-ig-fg:#9b1a64; --chip-ig-bd:#f3bcd9;   /* Instagram deliverables */\n  --chip-tt-fg:#22222f; --chip-tt-bd:#c9cad6;   /* TikTok deliverables */\n  --chip-ex-fg:#3a2db3; --chip-ex-bd:#cfc9f3;   /* event / usage rights / boosting */\n\n  /* ---------- Category chips ---------- */\n  --cat-bg:#efedf7; --cat-fg:#4b4780;\n\n  /* ---------- Spacing / geometry ---------- */\n  --page-w:1600px;\n  --page-h:1080px;          /* creator + overview pages; cover/closing are 900 */\n  --page-pad-x:52px;\n  --page-pad-top:30px;\n  --tray-gap:13px;          /* gap between cards */\n  --tray-pad:15px 17px 18px;\n  --card-pad:10px 10px 12px;\n  --portrait-h:232px;\n\n  --r-tray:20px;\n  --r-card:13px;\n  --r-portrait:9px;\n  --r-offer:10px;\n  --r-legend:12px;\n  --r-tag:5px;\n  --r-chip:6px;\n  --r-pill:20px;\n\n  --shadow-tray:0 22px 50px -30px rgba(0,0,0,.85);\n  --ez:cubic-bezier(.23,1,.32,1);\n}\n\n/* =====================================================================\n   CREATOR LIST \u00e2\u20ac\u201d COMPONENT STYLES\n   Requires tokens.css loaded first.\n   Class names that existed in the old template are kept where the\n   element survives (.page .ph .cards .creator-card .portrait .idx\n   .pb-stack .creator-identity .creator-tier .creator-categories\n   .creator-category). Everything under the portrait is new.\n   ===================================================================== */\n\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--navy);color:var(--on-dark);font-family:var(--font-sans);\n  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}\na{color:inherit}\n\n/* ---------------------------------------------------------------------\n   PAGE SHELL\n   --------------------------------------------------------------------- */\n.page{width:var(--page-w);height:var(--page-h);position:relative;overflow:hidden;\n  padding:var(--page-pad-top) var(--page-pad-x) 0;background:var(--navy);break-after:page}\n.page:last-child{break-after:auto}\n.page--cov,.page--end{height:900px;padding:0}\n\n/* footer: same on every page */\n.page footer{position:absolute;left:var(--page-pad-x);right:var(--page-pad-x);bottom:22px;\n  display:flex;align-items:center;gap:12px;font:500 11px/1 var(--font-mono);letter-spacing:.5px;color:var(--on-dark-3)}\n.page footer s{flex:1;height:1px;background:var(--line-dark);text-decoration:none}\n.page--cov footer,.page--end footer{left:60px;right:60px;color:#d8d5ea}\n.page--cov footer s,.page--end footer s{background:rgba(255,255,255,.22)}\n\n/* ---------------------------------------------------------------------\n   PAGE HEADER  (Thinkway | client logo + client + title + \"Creator List\" | range)\n   --------------------------------------------------------------------- */\n.ph{display:flex;align-items:center;gap:20px;height:56px}\n.ph__brand{height:26px;width:129px;display:block;flex:none}\n.ph__c{flex:1;display:flex;align-items:center;justify-content:center;gap:16px;min-width:0}\n.ph__client-logo{height:40px;width:auto;display:block}\n.ph__titles{display:flex;flex-direction:column;gap:3px;min-width:0}\n.ph__client{font-size:12px;color:var(--on-dark-2)}\n.ph__title{font-size:16px;font-weight:700;letter-spacing:-.2px}\n.ph__kind{font-size:11px;font-weight:600;letter-spacing:2.2px;text-transform:uppercase;color:var(--on-dark-3);margin-left:8px}\n.ph__r{display:flex;align-items:baseline;gap:7px;flex:none}\n.ph__r em{font-style:normal;font-size:17px;font-weight:700;color:var(--pink);font-variant-numeric:tabular-nums}\n.ph__r span{font-size:12px;color:var(--on-dark-3)}\n\n/* ---------------------------------------------------------------------\n   LEGEND BAR  (one per creator page, directly under the header)\n   --------------------------------------------------------------------- */\n.legend{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin:14px 0;padding:10px 18px;\n  background:var(--strip);border:1px solid rgba(255,255,255,.1);border-radius:var(--r-legend);\n  font-size:11.5px;color:var(--on-dark-2)}\n.legend__grp{display:flex;align-items:center;gap:8px}\n.legend__k{font-size:9.5px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:var(--on-dark-3);margin-right:2px}\n.legend__sep{width:1px;height:18px;background:var(--line-dark)}\n.legend b{color:var(--on-dark)}\n\n/* ---------------------------------------------------------------------\n   CARD TRAY\n   6 equal columns. Each card spans 6 implicit rows and uses SUBGRID,\n   so every zone (portrait, identity, audience, offer 1, offer 2,\n   categories) lines up horizontally across the whole row even when\n   one card's content is taller. This is the core of the redesign.\n   --------------------------------------------------------------------- */\n.cards{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-template-rows:repeat(6,auto);\n  column-gap:var(--tray-gap);row-gap:0;\n  background:linear-gradient(168deg,var(--panel-top),var(--panel) 62%);\n  border:1px solid var(--line-dark-2);border-radius:var(--r-tray);padding:var(--tray-pad);\n  box-shadow:var(--shadow-tray)}\n\n.creator-card{grid-row:span 6;display:grid;grid-template-rows:subgrid;row-gap:0;min-width:0;\n  background:var(--card);border-radius:var(--r-card);padding:var(--card-pad);color:var(--ink);\n  transition:transform .3s var(--ez),box-shadow .3s var(--ez)}\n/* Exactly SIX direct children, in this order:\n   .portrait  .creator-identity  .aud  .offer  .offer  .creator-categories\n   Never omit one: render an empty state instead, or rows misalign. */\n\n/* --- zone 1: portrait ------------------------------------------------ */\n.portrait{position:relative;display:block;height:var(--portrait-h);border-radius:var(--r-portrait);\n  overflow:hidden;background:var(--portrait-bg);text-decoration:none}\n.portrait>img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s var(--ez)}\n.idx{position:absolute;top:8px;left:8px;z-index:2;font:700 10px/1 var(--font-mono);letter-spacing:.6px;color:#fff;\n  background:rgba(8,6,66,.6);border:1px solid rgba(255,255,255,.22);border-radius:6px;padding:4px 6px}\n.pb-stack{position:absolute;top:6px;right:6px;z-index:2;display:flex}\n.pb-stack img{width:26px;height:26px;object-fit:contain;display:block}\n.pb-stack img+img{margin-left:-6px}\n\n/* --- zone 2: identity ------------------------------------------------ */\n.creator-identity{padding-top:10px;display:flex;flex-direction:column;gap:5px;min-width:0}\n.creator-name{margin:0;font-size:14.5px;line-height:18px;font-weight:700;letter-spacing:-.3px;\n  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.creator-meta{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.creator-handle{font:500 10.5px/14px var(--font-mono);color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.creator-tier{flex:none;font-size:9px;font-weight:700;letter-spacing:.7px;text-transform:uppercase;border-radius:var(--r-pill);padding:3px 8px}\n.creator-tier--mega{background:var(--mega-bg);color:var(--mega-fg)}\n.creator-tier--macro{background:var(--macro-bg);color:var(--macro-fg)}\n.creator-tier--mid{background:var(--mid-bg);color:var(--mid-fg)}\n.creator-tier--nano{background:var(--nano-bg);color:var(--nano-fg)}\n\n/* --- zone 3: audience table ------------------------------------------ */\n.aud{margin-top:10px;padding-top:8px;border-top:1px solid var(--hair)}\n.aud-row{display:grid;grid-template-columns:18px repeat(3,minmax(0,1fr));align-items:center;column-gap:4px;height:22px;\n  font-variant-numeric:tabular-nums}\n.aud-row>span{text-align:right;white-space:nowrap}\n.aud-row img{width:16px;height:16px;object-fit:contain;display:block}\n.aud-row--head{height:16px}\n.aud-row--head>span{font-size:8.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--ink-4)}\n.aud-f{font-size:12.5px;font-weight:700;color:var(--ink)}\n.aud-e,.aud-v{font-size:11.5px;font-weight:500;color:var(--ink-2)}\n.aud-row--off img{opacity:.35;filter:grayscale(1)}\n.aud-row--off .aud-f,.aud-row--off .aud-e,.aud-row--off .aud-v{color:var(--ink-off);font-weight:500}\n\n/* --- zones 4 + 5: offer blocks --------------------------------------- */\n.offer{margin-top:8px;border-radius:var(--r-offer);padding:9px 9px 8px;display:flex;flex-direction:column;gap:7px;min-width:0}\n.offer--1,.offer--pkg{background:var(--offer1-bg)}\n.offer--2{background:var(--offer2-bg)}\n.offer--empty{border:1px dashed var(--offer-empty);background:transparent;align-items:center;justify-content:center;\n  text-align:center;font-size:10.5px;font-style:italic;color:var(--ink-muted);min-height:56px}\n\n.offer-top{display:flex;align-items:center;justify-content:space-between;gap:6px}\n.offer-tag{flex:none;font-size:8.5px;font-weight:800;letter-spacing:1px;text-transform:uppercase;padding:3px 6px;border-radius:var(--r-tag)}\n.offer-tag--1,.offer-tag--pkg{background:var(--tag1-bg);color:var(--tag1-fg)}\n.offer-tag--2{background:var(--tag2-bg);color:var(--tag2-fg)}\n.offer-total{font-size:15px;font-weight:800;letter-spacing:-.4px;font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--ink)}\n.offer-total small{font-size:8.5px;font-weight:700;letter-spacing:.4px;color:var(--ink-3);margin-left:3px}\n.offer-usd{margin-top:-5px;text-align:right;font-size:10px;font-weight:600;color:var(--cat-fg);font-variant-numeric:tabular-nums}\n\n.chips{display:flex;flex-wrap:wrap;gap:4px}\n.chip{font-size:10px;line-height:13px;font-weight:600;padding:2px 6px;border-radius:var(--r-chip);background:#fff;border:1px solid}\n.chip--ig{color:var(--chip-ig-fg);border-color:var(--chip-ig-bd)}\n.chip--tt{color:var(--chip-tt-fg);border-color:var(--chip-tt-bd)}\n.chip--ex{color:var(--chip-ex-fg);border-color:var(--chip-ex-bd)}\n\n.offer-breakdown{margin-top:auto;display:flex;justify-content:space-between;gap:6px;padding-top:6px;\n  border-top:1px dashed var(--hair-dash);font-size:10px;color:var(--ink-3);font-variant-numeric:tabular-nums;white-space:nowrap}\n\n/* --- zone 6: categories ---------------------------------------------- */\n.creator-categories{padding-top:10px;display:flex;flex-wrap:wrap;gap:4px;align-content:flex-start}\n.creator-category{font-size:9.5px;line-height:12px;background:var(--cat-bg);color:var(--cat-fg);border-radius:10px;padding:3px 7px}\n\n/* ---------------------------------------------------------------------\n   NOTES PANEL \u00e2\u20ac\u201d fills leftover columns on the last creator page\n   (only when that page has \u00e2\u2030\u00a44 cards; spans the free columns)\n   --------------------------------------------------------------------- */\n.notes{grid-column:span 2;grid-row:span 6;align-self:start;margin-left:10px;padding:18px 20px 8px;\n  border:1px solid var(--line-dark);border-radius:var(--r-card);background:rgba(5,4,67,.45)}\n.notes__k{display:block;font-size:9.5px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--pink-soft);margin-bottom:12px}\n.note{display:flex;flex-direction:column;gap:4px;padding:12px 0;border-top:1px solid rgba(255,255,255,.12)}\n.note b{font-size:13px;font-weight:700;color:var(--on-dark)}\n.note span{font-size:12px;line-height:1.5;color:var(--on-dark-2)}\n\n/* ---------------------------------------------------------------------\n   AT-A-GLANCE TABLE PAGE\n   --------------------------------------------------------------------- */\n.glance-hd{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin:22px 0 16px}\n.glance-hd__eye{display:block;font-size:10.5px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:var(--pink-soft)}\n.glance-hd h1{margin:8px 0 0;font-size:34px;line-height:1.1;font-weight:800;letter-spacing:-1px}\n.glance-hd p{margin:0;font-size:12px;color:var(--on-dark-2);text-align:right}\n.glance{background:var(--card);color:var(--ink);border-radius:16px;padding:12px 14px 6px;box-shadow:var(--shadow-tray)}\n.gl-tr{display:grid;grid-template-columns:48px minmax(0,1fr) 82px 92px 72px 92px 92px 72px 92px 150px 150px;align-items:center}\n.gl-tr>*{padding:0 10px;white-space:nowrap}\n.gl-tr .r{text-align:right}\n.gl-groups{height:26px;font-size:9.5px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase}\n.gl-grp{grid-column:span 3;display:flex;align-items:center;justify-content:center;gap:6px;height:26px;border-bottom:2px solid}\n.gl-grp img{width:14px;height:14px}\n.gl-grp--ig{border-color:var(--chip-ig-bd);color:var(--chip-ig-fg)}\n.gl-grp--tt{border-color:var(--chip-tt-bd);color:var(--chip-tt-fg)}\n.gl-grp--offer{grid-column:span 2;border-color:var(--ink);color:var(--ink)}\n.gl-head{height:34px;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--ink-4);border-bottom:1px solid #e2e0ec}\n.gl-row{height:44px;font-size:13px;font-variant-numeric:tabular-nums;color:var(--ink-2);border-bottom:1px solid #efedf5}\n.gl-row:nth-child(even){background:#faf9fd}\n.gl-n{font:700 11px/1 var(--font-mono);color:var(--ink-muted)}\n.gl-who{display:flex;align-items:center;gap:10px;min-width:0;text-decoration:none}\n.gl-who img{width:30px;height:30px;border-radius:50%;object-fit:cover;flex:none}\n.gl-who div{display:flex;flex-direction:column;gap:3px;min-width:0}\n.gl-who b{font-size:13px;font-weight:700;color:var(--ink);overflow:hidden;text-overflow:ellipsis}\n.gl-who span{font:500 10.5px/1 var(--font-mono);color:var(--ink-3)}\n.gl-f{font-weight:700;color:var(--ink)}\n.gl-ig{background:rgba(255,61,168,.045)}\n.gl-tt{background:rgba(8,6,66,.03)}\n.gl-off,.gl-off .gl-f{color:var(--ink-off)}\n.gl-money{display:flex;align-items:center;justify-content:flex-end;gap:7px}\n.gl-money b{font-weight:800;color:var(--ink)}\n.gl-money .offer-tag{font-size:8px;padding:2px 5px;border-radius:4px}\n\n/* ---------------------------------------------------------------------\n   COVER + CLOSING (portrait wall)\n   --------------------------------------------------------------------- */\n.mosaic{position:absolute;inset:-20px;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));grid-auto-rows:240px;gap:3px;filter:saturate(.55)}\n.mosaic img{width:100%;height:100%;object-fit:cover;display:block;opacity:.42}\n.veil{position:absolute;inset:0;background:\n  radial-gradient(120% 95% at 8% 50%,rgba(5,4,67,.99) 26%,rgba(5,4,67,.86) 46%,rgba(5,4,67,.42) 72%,rgba(5,4,67,.26) 100%),\n  linear-gradient(180deg,rgba(5,4,67,.72),rgba(5,4,67,.20) 34%,rgba(5,4,67,.86))}\n.veil--end{background:\n  radial-gradient(130% 110% at 50% 46%,rgba(5,4,67,.97) 30%,rgba(5,4,67,.88) 58%,rgba(5,4,67,.55) 100%),\n  linear-gradient(180deg,rgba(5,4,67,.80),rgba(5,4,67,.30) 40%,rgba(5,4,67,.92))}\n\n.cov{position:relative;height:100%;padding:36px 60px 30px;display:flex;align-items:center;justify-content:space-between;gap:64px}\n.cov__main{display:flex;flex-direction:column;max-width:860px}\n.cov__brand{display:flex;align-items:center;gap:14px;margin-bottom:30px}\n.cov__rule{width:34px;height:1px;background:rgba(255,255,255,.22)}\n.cov__for{font-size:10.5px;font-weight:600;letter-spacing:2.4px;text-transform:uppercase;color:var(--on-dark-3)}\n.cov__recipient{margin:0 0 14px;font-size:22px;line-height:1.35}\n.cov h1{margin:0;font-size:56px;line-height:1.06;font-weight:800;letter-spacing:-1.6px;max-width:18ch}\n.cov__strip{display:flex;align-items:center;gap:14px;margin-top:26px;padding:11px 22px;background:rgba(37,34,95,.82);\n  border:1px solid var(--line-dark);border-radius:30px;width:max-content}\n.cov__strip b{font-size:14px;font-weight:700}\n.cov__strip i{width:3px;height:3px;border-radius:50%;background:var(--on-dark-3)}\n.cov__strip span{font:500 13px/1 var(--font-mono);color:var(--on-dark-2)}\n.cov__count{display:flex;align-items:center;gap:24px;margin-top:40px}\n.cov__count>b{font-size:132px;line-height:.84;font-weight:800;letter-spacing:-6px;color:var(--pink);font-variant-numeric:tabular-nums}\n.cov__count-txt{padding-left:24px;border-left:1px solid rgba(255,255,255,.18);display:flex;flex-direction:column;gap:10px}\n.cov__count-txt u{display:block;text-decoration:none;font-size:27px;font-weight:700;letter-spacing:-.6px;line-height:1.1}\n.cov__count-txt small{display:block;font-size:13.5px;color:var(--on-dark-2);margin-top:4px}\n.cov__tiers{display:flex;gap:6px;flex-wrap:wrap}\n.cov__tiers .creator-tier{font-size:11px;letter-spacing:.5px;padding:4px 10px}\n.cov__client-logo{width:400px;height:auto;display:block;flex:none;filter:drop-shadow(0 10px 18px rgba(0,0,0,.35))}\n\n.end{position:relative;height:100%;padding:0 60px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}\n.end__eye{font-size:10.5px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:var(--pink-soft)}\n.end h1{margin:14px 0 0;font-size:74px;line-height:1;font-weight:800;letter-spacing:-2.4px}\n.end p{margin:14px 0 0;font-size:14.5px;line-height:1.6;color:var(--on-dark-2)}\n.end__g{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:38px;width:100%;max-width:1080px}\n.bk{background:rgba(37,34,95,.7);border:1px solid var(--line-dark);border-radius:16px;padding:16px 18px 18px;text-align:left}\n.bk__k{display:block;font-size:9.5px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--on-dark-3);margin:0 0 12px}\n.bk__b{display:flex;flex-wrap:wrap;gap:8px 22px}\n.st{display:flex;align-items:baseline;gap:7px}\n.st b{font-size:25px;font-weight:800;letter-spacing:-.9px;color:#fff;font-variant-numeric:tabular-nums}\n.st span{font-size:11.5px;color:var(--on-dark-2)}\n.end__ft{display:flex;align-items:center;gap:14px;width:100%;max-width:1080px;margin-top:34px;padding-top:16px;border-top:1px solid var(--line-dark)}\n.end__ft span{flex:1}\n\n/* ---------------------------------------------------------------------\n   SCREEN-ONLY POLISH\n   --------------------------------------------------------------------- */\n@media screen{\n  .creator-card:hover{transform:translateY(-6px);box-shadow:0 20px 34px -18px rgba(0,0,0,.8),0 0 0 2px var(--pink)}\n  .creator-card:hover .portrait>img{transform:scale(1.05)}\n  .portrait:focus-visible{outline:3px solid var(--pink);outline-offset:2px}\n}\n@media screen and (max-width:1599px){.page{zoom:calc(100vw / 1600px)}}\n@media (prefers-reduced-motion:reduce){\n  .creator-card,.portrait>img{transition:none}\n  .creator-card:hover,.creator-card:hover .portrait>img{transform:none}\n}\n\n/* ---------------------------------------------------------------------\n   PRINT / PDF\n   Creator + overview pages are 1600\u00c3\u20141080; cover/closing 1600\u00c3\u2014900.\n   Named pages let one document mix both sizes.\n   --------------------------------------------------------------------- */\n@page{size:1600px 1080px;margin:0}\n@page short{size:1600px 900px;margin:0}\n.page--cov,.page--end{page:short}\n@media print{\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\n  .creator-card{box-shadow:none;border:1px solid #e6e3f0}\n  .cards,.glance{box-shadow:none}\n}\n";
